const s = $json;
const lines = [];
lines.push('🎯 *Targeting strategy — ' + (s.platform_identified || 'campaign') + '* (confidence: ' + (s.confidence || 'n/a') + ')');
lines.push('');
lines.push('*Summary:* ' + s.strategy_summary);
lines.push('*Audience approach:* ' + s.audience_approach);
lines.push('');
lines.push('*Segments:*');
for (const seg of s.segmentation || []) lines.push('  • ' + seg.segment + ' — ' + seg.rationale);
lines.push('*Budget split:*');
for (const b of s.budget_split || []) lines.push('  • ' + b.segment + ': ' + b.allocation + ' (' + b.note + ')');
if ((s.exclusions || []).length) lines.push('*Exclusions:* ' + s.exclusions.join(', '));
lines.push('*Setup notes:*');
for (const n of s.setup_notes || []) lines.push('  • ' + n);
lines.push('');
lines.push('⚠️ *Primary risk:* ' + s.primary_risk);
return [{ json: {
  plan_text: lines.join('\n'),
  strategy_summary: s.strategy_summary || '',
  audience_approach: s.audience_approach || ''
} }];

const brief = $('Campaign brief').first().json;
const plan = $('Format the plan').first().json;
let variants = [];
try {
  variants = JSON.parse($json.choices[0].message.content).variants || [];
} catch (e) {
  throw new Error('Could not parse OpenAI response as JSON');
}
return variants.map((v) => ({
  json: {
    headline: v.headline || '',
    primary_text: v.primary_text || v.body || '',
    platform: brief.platform || 'meta',
    product_context: brief.product || '',
    target_audience: plan.audience_approach || ''
  }
}));

const ad = $('Split into variants').item.json;
const fixes = $json.prioritized_fixes || [];
return [{ json: {
  status: $json.launch_recommendation === 'run' ? 'shippable' : 'needs one fix',
  headline: ad.headline,
  primary_text: ad.primary_text,
  platform: ad.platform,
  verdict: $json.launch_recommendation,
  score: $json.overall_score,
  top_fix: fixes.length ? (fixes[0].suggestion || fixes[0].issue || '') : ''
} }];
